from odoo.tools import SQL
from odoo.tools.module_data import rename_field

# The units were dateutil rrule frequency codes stored as text ("0" is YEARLY);
# they are the shared singular time units now, generated by the recurrence engine
# rather than rrule. `unit_of_time` pairs with `duration_count` as `duration_unit`.
# Renamed in place so columns keep their data and field rows their ids.
_UNITS = {"0": "year", "1": "month", "2": "week", "3": "day"}


def migrate(cr, version):
    if not version:
        return
    for model in ("date.range.type", "date.range.generator"):
        rename_field(cr, model, "unit_of_time", "duration_unit", values=_UNITS)
    for code, unit in _UNITS.items():
        cr.execute(
            SQL(
                "UPDATE date_range_type SET autogeneration_unit = %s"
                " WHERE autogeneration_unit = %s",
                unit,
                code,
            )
        )
